function initialLocale(): 'en' | 'th' {
  try {
    const l = localStorage.getItem('locale')
    if (l === 'en' || l === 'th') return l
  } catch {
    /* ignore */
  }
  return navigator.language.startsWith('th') ? 'th' : 'en'
}

i18n.use(initReactI18next).init({
  resources: { en: { translation: en }, th: { translation: th } },
  lng: initialLocale(),
  fallbackLng: 'en',
  interpolation: { escapeValue: false },
})

export function setLocale(l: 'en' | 'th') {
  // useMe() calls this from every component that uses it (one per card tile on a board), and i18next announces a
  // "change" even to the same language, re-rendering everything that translates: thousands of times on a big board.
  if (i18n.language === l && document.documentElement.lang === l) return
  i18n.changeLanguage(l)
  document.documentElement.lang = l
  try {
    localStorage.setItem('locale', l)
  } catch {
    /* ignore */
  }
}

/** Translate an API error code. */
export function errorText(e: unknown): string {
  const code = (e as { code?: string })?.code ?? 'internal'
  const data = (e as { data?: { retry_after?: number } })?.data
  // rate limited: say roughly how long to wait
  const minutes = Math.max(1, Math.ceil((data?.retry_after ?? 60) / 60))
  return i18n.exists(`errors.${code}`, { count: minutes }) ? i18n.t(`errors.${code}`, { count: minutes }) : i18n.t('errors.internal')
}

export default i18n
